// Recomputes and enforces the maximum pet count for the pet type associated with skill nSkillId. Iterates every skill listed in the pet type's nSkillId table, evaluates the petmax calc at the current skill level, and takes the highest result. Calls PETS_SetMaxAndTrimExcess to apply the new cap and kill excess pets. Only acts on player units with a valid pettype in D2PetTypeTxt.
void __fastcall SKILLS_UpdatePetMax(::SGAMEDATA * pGame, D2UnitStrc * pUnit, int32_t nSkillId) {
    D2SkillStrc* pSkill;
    int nSkillLvl;
    int nPetMaxCalc;
    eD2Skills eSkill;
    if (!(pUnit && pUnit->eUnitType == UNIT_PLAYER && nSkillId >= 0 && nSkillId < sgptDataTable->nTxtSkillsCount)) {
      return;
    }

    D2SkillsTxt* pSkillTxt = sgptDataTable->pTxtSkills + nSkillId;
    if (!pSkillTxt) {
      return;
    }

    uint8_t byPetType = pSkillTxt->pettype;
    if (!((char)byPetType > '\0' && (int)(char)byPetType < sgptDataTable->nTxtPetTypeSize)) {
      return;
    }

    D2PetTypeTxt* pPetTypeTxt = D2Client::GAME::RosterPets::GetPetTypeTxtById((int)(char)byPetType);
    if (!pPetTypeTxt) {
      return;
    }

    int nMaxPetCount = 0;
    int nSkillIdx = 0;
    if (0 < pPetTypeTxt->nSkillIndexCounter) {
      D2SkillsTxt* pPetSkillTxt;
      nSkillId = (int32_t)pPetTypeTxt->nSkillId;
      do {
        eSkill = (eD2Skills)*(short int*)nSkillId;
        pPetSkillTxt = D2Client::GAME::SCmd::TXT_Skills_GetLine(eSkill);
        if (pPetSkillTxt) {
          pSkill = D2Common::Skills::SKILLS_GetSkillByEnum(pUnit, eSkill);
          if (pSkill) {
            nSkillLvl = D2Common::Skills::GetSkillLevel(pUnit, pSkill, 1);
            nPetMaxCalc = 0;
            if (nSkillLvl > 0) {
              nPetMaxCalc = D2Common::Skills::D2GetSkillCalc(pUnit, pPetSkillTxt->petmax, eSkill, nSkillLvl);
              if (nPetMaxCalc < 1) {
                nPetMaxCalc = 1;
              }
            }
            if (nPetMaxCalc > nMaxPetCount) {
              nMaxPetCount = nPetMaxCalc;
            }
          }
        }

        nSkillId += 2;
        nSkillIdx++;
      } while (nSkillIdx < pPetTypeTxt->nSkillIndexCounter);
    }

    PLAYER::PlayerPets::PETS_SetMaxAndTrimExcess(pGame, pUnit, (int)pSkillTxt->pettype, nMaxPetCount);
}

